Power :: typeclass (T: type) {
    '<^>' :: (a: T, b: T) -> T #operator(right, 17);
}

ssize ::: instance Power {
    '<^>' :: (a: ssize, b: ssize) -> ssize #operator(right, 17) {
        r := 1;
        i := 0;
        while i < b { r *= a; i += 1; }
        return r;
    }
}

