#import "Io";
#import "Meta";

Particle :: struct { id: u8; x: s64; y: s64; }

total_x :: (v: #soa []mut Particle) -> s64 {
    total: s64 = 0;
    for i: 0..v.count total += v.x[i];
    return total;
}

scale_y :: (v: #soa []mut Particle, k: s64) {
    for i: 0..v.count v.y[i] *= k;
}

main :: () {
    soa: #soa [..]Particle;
    defer soa.free();
    soa.push(Particle.{ 1, 10, 20 });
    soa.push(Particle.{ 2, 30, 40 });

    v := soa.view();
    print("view type=% size=%\n", type_name(type_of(v)), size_of(type_of(v)));
    print("total_x=%\n", total_x(v));
    scale_y(v, 10);
    print("y=% %\n", soa.y[0], soa.y[1]);
}

#import "Io";

Vec2 :: struct #derive(Show) { x: s64 = 0; y: s64 = 0; }

main :: () {
    a := Vec2.{ 10, 20 };        // qualified: the type is written
    b: Vec2 = .{ 30, 40 };       // inferred: the annotation supplies it
    c: Vec2 = .{ .y = 7 };       // named, partial; x keeps its default
