Propagate :: typeclass (From: type, To: type) {
    propagate :: (#empty: To, value: From) -> To;
}

Try_Branch :: union {
    Continue: $T;
    Break: $R;
}

Try :: typeclass (Carrier: type)
    #minimal(from_output, from_residual, branch) {
    Output :: type;
    Residual :: type;

    from_output :: (#empty: Carrier, output: Output) -> Carrier;
    from_residual :: (#empty: Carrier, residual: Residual) -> Carrier;
    branch :: (value: Carrier) -> Try_Branch(Output, Residual);

    '?' :: (#empty: $Target, value: Carrier)
        -> Try_Branch(Output, Target)
        #operator(suffix, try(Target))
        where Try(Target) &&
            (Try(Carrier).Residual == Try(Target).Residual ||
             Propagate(Try(Carrier).Residual, Try(Target).Residual)) {
        if branch(value) == {
            case .Continue(output);
                #if Try(Carrier).Output == void return .Continue;
                else return .Continue(output);
            case .Break(residual);
                #if Try(Carrier).Residual == Try(Target).Residual {
                    return .Break(from_residual(Target, residual));
                } else {
                    converted := propagate(Try(Target).Residual, residual);
                    return .Break(from_residual(Target, converted));
                }
        }
    }
}

#import "Io";

fetch :: (ok: bool) -> string!s64 {
    if !ok return .Err("bad input");
    return .Ok(20);
}

sugared :: (ok: bool) -> string!s64 {
    v := fetch(ok)?;
    return v + 1;
}

expanded :: (ok: bool) -> string!s64 {
    v: s64;
    token := '?'(string!s64, fetch(ok));
    if token == {
        case .Continue(output); v = output;
        case .Break(carrier);   return carrier;
    }
    return from_output(string!s64, v + 1);
}

report :: (r: string!s64) -> string {
    if r == {
        case .Ok(v);  return show(v);
        case .Err(e); return e;
    }
}

main :: () {
    print("sugared  % %\n", report(sugared(true)), report(sugared(false)));
    print("expanded % %\n", report(expanded(true)), report(expanded(false)));
}

