Iterable :: typeclass (T: type) {
    for_expansion :: (val: T, body: Code, reverse: bool) #expand;
}

PointerIterable :: typeclass (T: type) where Iterable(T) {
    for_pointer_expansion :: (val: *mut T, body: Code, reverse: bool) #expand
}

#import "Io";

Countdown :: struct { from: ssize; }

Countdown ::: instance Iterable {
    for_expansion :: (value: Countdown, body: Code, reverse: bool) #expand {
        c := value;
        cursor: ssize = 0;
        while cursor < c.from {
            step := cursor;
            cursor += 1;
            `it_index := step;
            #if reverse {
                `it := step + 1;
            } else {
                `it := c.from - step;
            }
            #insert body;
        }
    }
}

main :: () {
    c: Countdown = .{ .from = 4 };
    for c print("% (index %)\n", it, it_index);
    for x: c print("named %\n", x);
    for < c print("reversed %\n", it);
}

