Iterable :: typeclass (T: type) {
    for_expansion :: (val: T, body: Code, reverse: bool) #expand;
}

PointerIterable :: typeclass (T: type) where Iterable(T) {
    for_pointer_expansion :: (val: *mut T, body: Code, reverse: bool) #expand
}

#import "Io";

Node :: struct { value: s64; next: ?*mut Node; }
List :: struct { head: ?*mut Node; }

List ::: instance Iterable {
    for_expansion :: (list: List, body: Code, reverse: bool) #expand {
        cursor := list.head;
        step := 0;
        while #pattern .Some(node) = cursor {
            `it := node.*.value;
            `it_index := step;
            cursor = node.*.next;
            step += 1;
            #insert body;
        }
    }
}

main :: () {
    c: Node = .{ .value = 30, .next = .None };
    b: Node = .{ .value = 20, .next = .Some(&c) };
    a: Node = .{ .value = 10, .next = .Some(&b) };
    list: List = .{ .head = .Some(&a) };

    for list print("default names: % at %\n", it, it_index);

    total := 0;
    for value, index: list { total += value; print("named: % at %\n", value, index); }
    print("total = %\n", total);
}

#import "Io";

Ring :: struct { items: [8]s64; start: ssize; count: ssize; }

ring_push :: (r: *mut Ring, value: s64) {
    r.*.items[(r.*.start + r.*.count) % 8] = value;
    r.*.count += 1;
}

Ring ::: instance Iterable {
    for_expansion :: (r: Ring, body: Code, reverse: bool) #expand {
        step := 0;
        while step < r.count {
            offset := ifx reverse r.count - 1 - step else step;
            `it := r.items[(r.start + offset) % 8];
            `it_index := step;
            step += 1;
            #insert body;
        }
    }
}

main :: () {
    r: Ring;
    r.start = 6;
    ring_push(&r, 10);
    ring_push(&r, 20);
    ring_push(&r, 30);

    for r print("% at %\n", it, it_index);
    for < v, i: r print("reverse % at %\n", v, i);
    for v: r { if v == 20 continue; print("kept %\n", v); }
}

#import "Io";

Span :: struct { start: s64; count: ssize; }

stepping :: (s: Span, body: Code, reverse: bool) #expand {
    step := 0;
    while step < s.count {
        `it := s.start + step * 2;
        `it_index := step;
        step += 1;
        #insert body;
    }
}

main :: () {
    s: Span = .{ .start = 100, .count = 3 };
    for :stepping v, i: s print("stepping % at %\n", v, i);
    for :for_expansion v, i: 1..4 print("explicit builtin % at %\n", v, i);
}

