        co.destroy();
    }
}

#import "Io";
#import "Jump";

waiter :: (data: ?*mut void) -> any {
    if #pattern .Some(p) = data {
        value := (cast(*mut Awaitable)p).co_await();
        print("ready=%\n", value);
        return 9;
    }
    return 0;
}

main :: () {
    scheduler: Scheduler;
    awaitable: Awaitable;
    awaitable.init();

    created := Coroutine.coroutine_create(waiter, cast(*mut void)&awaitable, .scheduler = &scheduler);
    if #pattern .Some(co) = created {
        (&scheduler).scheduler_enqueue(co);
        scheduler.run();
        print("waiting=%\n", co.*.status == .Waiting);
        awaitable.complete(7);
        scheduler.run();
        print("done=%\n", co.*.status == .Done);
        co.destroy();
    }
}

