requests: ssize = 0;

tracking_proc :: (
    data: ?*mut void,
    mode: Allocator_Mode,
    size: ssize,
    alignment: ssize,
    old_memory: ?*mut void,
    old_size: ssize
) -> ?*mut void  {
    heap := heap_allocator();
    if mode == {
        case .Alloc, .Alloc_Non_Zeroed;
            requests += 1;
            return mem_alloc(size, heap);
        case .Resize, .Resize_Non_Zeroed;
            requests += 1;
            if #pattern .Some(old) = old_memory {
                return old.mem_resize(old_size, size, heap);
            }
            return mem_alloc(size, heap);
        case .Free;
            old_memory.mem_free(heap);
            return .None;
        else;
            return .None;
    }
}

tracking_allocator :: () -> Allocator  {
    a: Allocator;
    a.procedure = tracking_proc;
    a.data = .None;
    return a;
}

main :: () {
    #push_allocator(tracking_allocator());
    text := format("%-%", 1, 2);
    print("% after % request(s)\n", text, requests);
    text.free();
}

